const clean = (items) => items.map(i => i.json || {}).filter(x => Object.keys(x).length);
const runs = clean($items('Get Recent Runs'));
const heartbeats = clean($items('Get Dashboard Heartbeats'));
const deadLetters = clean($items('Get Dashboard Dead Letters')).filter(x => !['resolved', 'ignored'].includes(String(x.review_status || '').toLowerCase()));
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const row = (cells) => '<tr>' + cells.map(v => '<td>' + esc(v) + '</td>').join('') + '</tr>';
const runRows = runs.slice(0, 50).map(r => row([r.started_at, r.workflow_key, r.run_id, r.status, r.error_summary])).join('') || '<tr><td colspan="5">No run data</td></tr>';
const heartbeatRows = heartbeats.map(h => row([h.workflow_key, h.schedule_key, h.last_seen_at, h.status, h.alerted_at])).join('') || '<tr><td colspan="5">No heartbeat data</td></tr>';
const dlqRows = deadLetters.slice(0, 100).map(d => row([d.created_at, d.workflow_key, d.dead_letter_id, d.failed_node, d.review_status])).join('') || '<tr><td colspan="5">No unresolved dead letters</td></tr>';
const failed = runs.filter(r => String(r.status).toLowerCase() === 'failed').length;
const missed = heartbeats.filter(h => String(h.status).toLowerCase() === 'missed').length;
const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>n8n Operations Health</title><style>body{font-family:system-ui,sans-serif;margin:2rem;color:#17202a}h1,h2{margin:.4rem 0 1rem}.cards{display:flex;gap:1rem;flex-wrap:wrap}.card{border:1px solid #ccd1d1;border-radius:10px;padding:1rem;min-width:10rem}.bad{color:#a93226}table{border-collapse:collapse;width:100%;margin:1rem 0 2rem;font-size:.9rem}th,td{border:1px solid #ddd;padding:.45rem;text-align:left;vertical-align:top}th{background:#f4f6f7}</style></head><body><h1>n8n Operations Health</h1><p>Generated ${esc(new Date().toISOString())}. Values are sanitized operational excerpts.</p><div class="cards"><div class="card"><b>Recent runs</b><br>${runs.length}</div><div class="card"><b>Failures</b><br><span class="bad">${failed}</span></div><div class="card"><b>Unresolved dead letters</b><br><span class="bad">${deadLetters.length}</span></div><div class="card"><b>Missed heartbeats</b><br><span class="bad">${missed}</span></div></div><h2>Recent runs</h2><table><thead><tr><th>Started</th><th>Workflow</th><th>Run ID</th><th>Status</th><th>Error summary</th></tr></thead><tbody>${runRows}</tbody></table><h2>Unresolved dead letters</h2><table><thead><tr><th>Created</th><th>Workflow</th><th>ID</th><th>Failed node</th><th>Review</th></tr></thead><tbody>${dlqRows}</tbody></table><h2>Heartbeats</h2><table><thead><tr><th>Workflow</th><th>Schedule</th><th>Last success</th><th>Status</th><th>Alerted</th></tr></thead><tbody>${heartbeatRows}</tbody></table></body></html>`;
return [{ json: { html } }];
